input.sparql:
SELECT ?zone_ref ?cooling_setpoint_ref ?heating_setpoint_ref
WHERE {
  ?zone a brick:Zone ;
    brick:hasHeatingSetpoint ?heating ;
    brick:hasCoolingSetpoint ?cooling .
  ?heating ref:hasExternalReference ?heating_ref .
  ?cooling ref:hasExternalReference ?cooling_ref .
  ?zone ref:hasExternalReference ?zone_ref .
  FILTER (
    ?zone_ref = brick:Core_mid
  )
}
